try:
    q1 = Quaternion(1, 0, 0, 0)
    result1 = q1.log()
    probe("Quaternion(1, 0, 0, 0).log()", result1)
except Exception as e:
    probe("Quaternion(1, 0, 0, 0).log()", "__error__: " + type(e).__name__ + ": " + str(e))

